const key = 'yeocheon-season-one-v1';
function persist(name,value){try{localStorage.setItem(key+name,JSON.stringify(value));return true}catch{return false}}
function restore(name,fallback){try{return JSON.parse(localStorage.getItem(key+name)) ?? fallback}catch{return fallback}}
const threeChoiceOrders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
function newChoiceOrders(){
  return Array.from({length:14},()=>Math.floor(Math.random()*threeChoiceOrders.length));
}
function initial(){
  return {page:-1,rank:null,route:0,flags:[],echo:'',moves:[],ending:null,choiceOrders:newChoiceOrders()};
}
function presentChoices(choices,page){
  const affectsRank=page===3||page===4||(page>=6&&page<=13);
  if(!affectsRank||choices.length<2)return choices;
  // Persist the order of each decision, without changing what any choice does.
  const index=state.choiceOrders[page];
  const order=choices.length===2?(index%2===0?[0,1]:[1,0]):threeChoiceOrders[index];
  return order.map(position=>choices[position]);
}
let state=restore('progress',initial());
const allowedEndings=[[0],[0,2],[0,2],[0,2],[0,2],[0,1,2]];
const validEndingIds=new Set(allowedEndings.flatMap((list,rank)=>list.map(ending=>rank*3+ending)));
let unlocked=restore('endingsV2',null);
if(state.page===15 && state.departureRank===undefined){
  state.departureRank=onwardRank(state.rank,state.ending);
  persist('progress',state);
}
if(unlocked===null){
  unlocked=restore('endings',[]).filter(id=>validEndingIds.has(id)&&id!==0&&id!==5);
  persist('endingsV2',unlocked);
  if(state.page===15 && (!allowedEndings[state.rank].includes(state.ending)||state.rank===0||(state.rank===1&&state.ending===2))){
    state.page=14;
    state.ending=null;
    state.departureRank=undefined;
    state.rankLead=undefined;
    state.rankLeadRead=undefined;
    persist('progress',state);
  }
}
const reader=document.querySelector('#reader');
const music=document.querySelector('#music');
const musicToggle=document.querySelector('#music-toggle');
const saveButton=document.querySelector('#save-progress');
const loadButton=document.querySelector('#load-progress');
const saveStatus=document.querySelector('#save-status');
const saveTime=new Intl.DateTimeFormat('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});

function refreshSaveControls(message){
  const mark=restore('manualBookmark',null);
  saveButton.disabled=state.page===-1;
  loadButton.disabled=!mark?.progress;
  saveStatus.textContent=message??(mark?.progress?'저장 장면 · '+mark.title+' · '+saveTime.format(mark.savedAt):'수동 저장 기록 없음');
}
saveButton.onclick=()=>{
  if(state.page===-1)return;
  const title=reader.querySelector('h1,h2')?.textContent||'읽던 장면';
  const saved=persist('manualBookmark',{progress:state,title,savedAt:Date.now()});
  refreshSaveControls(saved?'저장됨 · '+title:'브라우저에 저장할 수 없습니다.');
};
loadButton.onclick=()=>{
  const mark=restore('manualBookmark',null);
  if(!mark?.progress)return;
  // The bookmark is independent of the automatic continuation and ending collection.
  commit(()=>{state=mark.progress});
  refreshSaveControls('불러옴 · '+mark.title);
};
const tracks=['after-rain','night-ferry','spring'];
let musicEnabled=restore('music',true);
let musicStarted=false;
let currentTrack='';
music.volume=.32;

function updateMusicControl(){
  const playing=musicEnabled && musicStarted && !music.paused;
  musicToggle.textContent=playing?'배경음악 끄기':'배경음악 켜기';
  musicToggle.setAttribute('aria-pressed',String(playing));
}

function syncMusic(){
  if(!musicEnabled || !musicStarted){music.pause();updateMusicControl();return;}
  const track=tracks[state.page>=15?2:state.page>=5?1:0];
  if(track!==currentTrack){
    music.src='audio/'+track+'.mp3';
    currentTrack=track;
    music.play().catch(updateMusicControl);
  }else if(music.paused){
    music.play().catch(updateMusicControl);
  }
}

music.addEventListener('play',updateMusicControl);
music.addEventListener('pause',updateMusicControl);
music.addEventListener('error',updateMusicControl);
musicToggle.onclick=()=>{
  musicEnabled=!(musicStarted && musicEnabled && !music.paused);
  musicStarted=true;
  persist('music',musicEnabled);
  syncMusic();
};
const panelLabels=['홍수가 지나간 여천','쌀자루를 내미는 소복과 이서','장부를 펼친 관아','어두운 강에 정박한 나룻배','불이 켜진 사랑채','새벽 강가의 이서와 아이들'];
function panel(id,caption){
  return '<figure class="panel" role="img" aria-label="'+panelLabels[id]+'" style="background-position:'+(id%3*50)+'% '+(id>2?100:0)+'%"><figcaption>'+caption+'</figcaption></figure>';
}
function commit(mutation){mutation();musicStarted=true;persist('progress',state);render(true);syncMusic()}
function control(label,action,note='',primary=false){return {label,action,note,primary}}
function moveAvailable(rank,delta,stage) {
  const target=rank+delta;
  return target>=0 && target<ranks.length && (Math.abs(delta)===1 || state.flags.includes('neighbors') || state.flags.includes(stage===6?'sailor':'nurse') || state.moves.some(move=>move!==0));
}
