function contextualScene(page){
  const [id,baseCaption,baseLines,stakes]=connectiveScenes[page];
  let caption=baseCaption;
  let lines=baseLines;
  if(page===1)lines=withFlag(baseLines,branchLines.first);
  if(page===2)lines=withFlag(baseLines,branchLines.name);
  if(page===3)lines=withFlag(baseLines,branchLines.funding);
  if(page===4){
    caption+=' '+routeContext[state.route];
    lines=branchLines.route[state.route];
  }
  if(page===5)lines=[...branchLines.reveal[state.rank],baseLines[0]];
  if(page>=7 && page<=14){
    const stage=page-7;
    const move=state.moves[stage];
    if(move!==undefined&&!state.interlude&&!state.arrivedFromBridge){
      const previousRank=state.rank-move;
      const matchesScene=stage>=5||move===0||Math.min(previousRank,state.rank)===stage;
      lines=matchesScene?branchLines.moves[stage][move===0?0:move>0?1:2]:branchLines.other[stage];

    }
  }
  if((state.interlude||state.arrivedFromBridge)&&page!==4)lines=[];
  const [nextCaption,nextLines,nextStakes]=caseConversation(page,lines);
  return [id,nextCaption,nextLines,nextStakes];
}
